Total: {{
  (() => {
    const items = get_carrito_actual.data || [];
    const movs = get_saldo_ciclos_anteriores.data || [];
    const subtotal = items.reduce((acc, p) => acc + Number(p.subtotal || 0), 0);
    const recargo = items.reduce((acc, p) => acc + Number(p.recargo || 0), 0);
    const saldoAnterior = movs.reduce((acc, m) => acc + (m.tipo === 'cargo' ? Number(m.monto) : -Number(m.monto)), 0);
    const total = Math.max(0, subtotal + recargo + saldoAnterior);
    return total.toLocaleString('es-CL', { style: 'currency', currency: 'CLP' });
  })()
}}
